-- Batch E (verified contacts read in Chrome 2026-11-19), online-only rule. No fs_partner_activity rows. No sends.
-- Guard: id AND exact current status/next_step_due AND exact old next_step AND marker absent.
-- Marker: [contacts-E 2026-11-19]
begin;
-- (a) On-Stage grant
update fs_grant_deadlines set status='ready', next_step=$t$Online only: Stephen emails Alman Nusrat (Marketing Manager, acn@musicpeopleinc.com) first, not both contacts, on Mon Nov 23. Two sentences plus the deck link https://selassiefest.com/full-spectrum/deck.html. Ask for an in-kind donation or loan of specified stands (13 laptop stands, $455 line, packet 02-gear-audio) and, failing that, demo/open-box stock or a dealer introduction. Alternate: Jeremy Payne (Sr. Director, M.I. Business Unit, jmp@musicpeopleinc.com). Same stands line also asked of Gator; first yes wins. Stephen sends only after saying send.$t$, next_step_due='2026-11-23', notes=coalesce(notes,'')||chr(10)||$t$[contacts-E 2026-11-19] status was skip, now to_research (route unverified); next_step_due was null, now 2026-11-23; reason: published staff contacts found. Verified in Chrome Nov 19, 2026: https://on-stage.com/about team table lists Alman Nusrat, Marketing Manager (acn@musicpeopleinc.com) and Jeremy Payne, Sr. Director- M.I. Business Unit (jmp@musicpeopleinc.com); https://on-stage.com/team/JeremyPayne tagline says he provides direction for the marketing efforts of the On-Stage family of brands; Jay Jasch, Creative Director (jcj@musicpeopleinc.com) also listed. No community, education or artist-relations title is listed: these are published business contacts, NOT confirmed donation decision-makers. UNVERIFIED precedent claim from outside research (svconline.com article): On-Stage donated stands/racks through Music Will in 2026; verify before citing to the funder. Amount asked: 13 laptop stands ($455 line). Prior skip note (no electronic route) superseded.$t$ where id='a4287c9e-7de0-4540-83df-cfa63c3850bc' and status='skip' and next_step_due is null and next_step=$t$SKIP: no electronic route found (phone and Berlin CT mail address only). Stands line stays with Gator.$t$ and coalesce(notes,'') not like '%[contacts-E 2026-11-19]%'; -- On-Stage grant
-- On-Stage partner
update fs_partners set ball_with='us', next_step_due='2026-11-23', email='acn@musicpeopleinc.com', contacts=$t$[{"name":"Alman Nusrat","role":"Marketing Manager","email":"acn@musicpeopleinc.com","note":"first contact; published business contact on on-stage.com/about, not a confirmed donation decision-maker"},{"name":"Jeremy Payne","role":"Sr. Director- M.I. Business Unit","email":"jmp@musicpeopleinc.com","note":"alternate; on-stage.com/team/JeremyPayne says he directs marketing for the On-Stage family of brands"}]$t$::jsonb, next_step=$t$Online only: Stephen emails Alman Nusrat (acn@musicpeopleinc.com) first on Mon Nov 23: two sentences plus the deck link https://selassiefest.com/full-spectrum/deck.html; ask about an in-kind donation or loan of 13 laptop stands ($455 line, packet 02-gear-audio) and, failing that, demo/open-box stock or a dealer introduction. Alternate: Jeremy Payne (jmp@musicpeopleinc.com). See grant row a4287c9e. Stephen sends only after saying send.$t$, notes=coalesce(notes,'')||chr(10)||$t$2026-11-19 [contacts-E 2026-11-19] ball_with was parked, now us; next_step_due was null, now 2026-11-23; email and contacts were empty, now filled. Source: https://on-stage.com/about (team table) and https://on-stage.com/team/JeremyPayne, read in Chrome Nov 19, 2026. Published business contacts only; donation decision-maker unconfirmed. Music Will 2026 stand/rack donation is an UNVERIFIED outside-research claim (svconline.com).$t$ where id='414dde79-6b11-4c98-ae44-dcdc579bcb64' and ball_with='parked' and next_step_due is null and email is null and contacts='[]'::jsonb and next_step=$t$PARKED: no electronic route for On-Stage / The Music People (phone and mail address only). Stands line stays with Gator (see grant row a4287c9e).$t$ and coalesce(notes,'') not like '%[contacts-E 2026-11-19]%'; -- On-Stage partner
-- (b) Gator grant
update fs_grant_deadlines set url='https://gatorbiz.typeform.com/to/MSvbqK', next_step=$t$Stephen submits the Gator contact request online by Mon Nov 23 at https://gatorbiz.typeform.com/to/MSvbqK (the Typeform embedded in https://gatorco.com/contact/; first question: Are you located in the United States?). Ask who handles community/education donations and request 13 laptop stands ($455 line). Packet 02-gear-audio/03-gator.md. Same stands line asked of On-Stage; first yes wins. Stephen submits only after saying send.$t$, notes=coalesce(notes,'')||chr(10)||$t$[contacts-E 2026-11-19] url was https://gatorco.com/contact/, now the Typeform direct link; status ready and due 2026-11-23 unchanged. Verified in Chrome Nov 19, 2026: gatorco.com/contact/ embeds https://gatorbiz.typeform.com/to/MSvbqK, live, titled Contact Us. UNVERIFIED (PDF unreadable): Gator's April 2026 education guide reportedly says a portion of band/orchestral sales supports music education; no donation program confirmed. The Oct 31 note saying no form existed is superseded.$t$ where id='de947322-dbc9-4af0-80b9-713f47fb844a' and status='ready' and next_step_due::date='2026-11-23' and url='https://gatorco.com/contact/' and next_step=$t$Stephen submits the Gator contact request at https://gatorco.com/contact/ ("Submit a contact request"): ask who handles community/education donations and request 13 laptop stands ($455 line). Packet 02-gear-audio/03-gator.md. Same stands line asked of On-Stage; first yes wins.$t$ and coalesce(notes,'') not like '%[contacts-E 2026-11-19]%'; -- Gator grant
-- Gator partner
update fs_partners set next_step=$t$Online only: Stephen submits the Gator Typeform https://gatorbiz.typeform.com/to/MSvbqK (embedded on https://gatorco.com/contact/; see grant row de947322) by Mon Nov 23, asking who handles community/education donations. Stephen submits only after saying send.$t$, notes=coalesce(notes,'')||chr(10)||$t$2026-11-19 [contacts-E 2026-11-19] next_step now points to the Typeform direct link (verified live in Chrome Nov 19, 2026); due 2026-11-23 and ball_with us unchanged. Gator April 2026 education-guide claim is UNVERIFIED.$t$ where id='d8211717-4fab-4c5d-86ab-ff62b95010e2' and next_step_due::date='2026-11-23' and ball_with='us' and next_step=$t$Online only: Stephen submits the Gator contact request at https://gatorco.com/contact/ (see grant row de947322), asking who handles community/education donations.$t$ and coalesce(notes,'') not like '%[contacts-E 2026-11-19]%'; -- Gator partner
-- (c) Barry Callebaut grant (reopens the Batch C skip)
update fs_grant_deadlines set status='to_research', next_step=$t$Sponsorship REFERRAL (not a grant; decision-maker unverified). Online only: Stephen emails Sharene Shariatzadeh (Sharene@LUMA8.org) on Mon Nov 23, asking whether she can point us to the right Barry Callebaut contact, if Barry Callebaut was involved with Arts in the Dark (its news story says it sponsored the Chicago Halloweek parade). Two sentences plus the deck link https://selassiefest.com/full-spectrum/deck.html. Fallback: Barry Callebaut Head Office web form https://www.callebaut.com/en-US/contact-us?department=2448 with Subject "Other requests" (no community/donation option exists). Stephen sends only after saying send.$t$, next_step_due='2026-11-23', notes=coalesce(notes,'')||chr(10)||$t$[contacts-E 2026-11-19] status was skip, now to_research (route unverified); next_step_due was null, now 2026-11-23; reason: a referral route was found, reversing the Batch C skip. Verified in Chrome Nov 19, 2026: https://artsinthedark.com/contact/ says For more information on LUMA8, sponsorship or participation in our events, contact: Sharene Shariatzadeh. Barry Callebaut was a lead sponsor of the City of Chicago's Halloweek/Arts in the Dark parade (barry-callebaut.com news story, found by search); the Arts in the Dark contact page does NOT mention Barry Callebaut, so Sharene is an event contact, not a confirmed Barry Callebaut link. This is a sponsorship referral, not a grant. Head Office form https://www.callebaut.com/en-US/contact-us?department=2448 has Subject options including Other requests; US office 600 West Chicago Ave Suite 860, Chicago. Snacks line ($6,000 ask) unchanged.$t$ where id='e562dd73-084f-45fa-be5f-5c8e8bca8910' and status='skip' and next_step_due is null and next_step=$t$Skip: no electronic donation route found. Chrome check Nov 19, 2026: barry-callebaut.com/en/about-us/contact is Page not found; cacao-barry.com contact is a department-picker form (Sales, Head Office, Customer Care, Media). Reopen if a community-giving email or form appears.$t$ and coalesce(notes,'') not like '%[contacts-E 2026-11-19]%'; -- Barry grant
-- Barry Callebaut partner
update fs_partners set ball_with='us', next_step_due='2026-11-23', next_step=$t$Sponsorship referral (not a grant; decision-maker unverified). Online only: Stephen emails Sharene Shariatzadeh (Sharene@LUMA8.org, LUMA8 / Arts in the Dark) on Mon Nov 23 asking whether she can point us to the right Barry Callebaut contact, if Barry Callebaut was involved with Arts in the Dark; deck link https://selassiefest.com/full-spectrum/deck.html. Fallback: Head Office form https://www.callebaut.com/en-US/contact-us?department=2448, Subject "Other requests". See grant row e562dd73 and the LUMA8 row. Stephen sends only after saying send.$t$, notes=coalesce(notes,'')||chr(10)||$t$2026-11-19 [contacts-E 2026-11-19] ball_with was parked, now us; next_step_due was null, now 2026-11-23; reason: referral route via https://artsinthedark.com/contact/ (read in Chrome Nov 19, 2026) reverses the Batch C park. It is a sponsorship referral, not a grant, and the Barry Callebaut decision-maker is unverified; the Arts in the Dark page does not mention Barry Callebaut.$t$ where id='6e21e33a-c72b-4133-a646-f552e5087f01' and ball_with='parked' and next_step_due is null and next_step like 'Parked: no electronic donation route. Chrome check Nov 19, 2026:%' and coalesce(notes,'') not like '%[contacts-E 2026-11-19]%'; -- Barry partner
-- (d) New referral partner row: LUMA8 / Arts in the Dark (live search found none)
insert into fs_partners (id, name, category, email, website, contacts, stage, ball_with, next_step, next_step_due, source, notes)
select 'b7c1e5a2-3d4f-4a6b-9c8d-1e2f3a4b5c6d'::uuid, $t$LUMA8 / Arts in the Dark (Barry Callebaut referral)$t$, 'Other', 'Sharene@LUMA8.org', 'https://artsinthedark.com/contact/',
 $t$[{"name":"Sharene Shariatzadeh","email":"Sharene@LUMA8.org","note":"published sponsorship contact for LUMA8 / Arts in the Dark events"}]$t$::jsonb,
 'not_contacted', 'us',
 $t$Online only: Stephen emails Sharene Shariatzadeh (Sharene@LUMA8.org) on Mon Nov 23 asking whether she can point us to the right Barry Callebaut contact, if Barry Callebaut was involved with Arts in the Dark; two sentences plus the deck link https://selassiefest.com/full-spectrum/deck.html. See Barry Callebaut grant e562dd73 and partner 6e21e33a. Stephen sends only after saying send.$t$,
 '2026-11-23', $t$Verified contact page https://artsinthedark.com/contact/ read in Chrome 2026-11-19$t$,
 $t$2026-11-19 [contacts-E 2026-11-19] Created as a REFERRAL partner only (not a funder). The contact page says: For more information on LUMA8, sponsorship or participation in our events, contact Sharene Shariatzadeh. The page does not mention Barry Callebaut; the Barry Callebaut Halloweek/Arts in the Dark lead-sponsor link comes from a barry-callebaut.com news story found by search. No outreach yet. See also Goodwill 8ad67167 (also at Arts in the Dark).$t$
where not exists (select 1 from fs_partners where id='b7c1e5a2-3d4f-4a6b-9c8d-1e2f3a4b5c6d') and not exists (select 1 from fs_partners where email ilike 'Sharene@LUMA8.org' or name ilike '%LUMA8%');
-- (e) Costco: note only (grant row)
update fs_grant_deadlines set notes=coalesce(notes,'')||chr(10)||$t$[contacts-E 2026-11-19] No status or date change. Route stays online only: Costco Grant Application via Benevity (application-preparer reads it first). The paper warehouse-form route is submitted in person at the nearest warehouse, which Stephen's no-visit rule excludes. The Chicago South Loop warehouse (1430 S. Ashland Ave) exists but is not used.$t$ where id='94f4ffa2-ecf9-4a08-ad80-453c6becb9a5' and status='ready' and next_step_due::date='2026-11-23' and coalesce(notes,'') not like '%[contacts-E 2026-11-19]%';
-- (f) D'Addario Foundation partner: stale date only (step has no phone/visit)
update fs_partners set next_step_due='2027-01-11', notes=coalesce(notes,'')||chr(10)||$t$2026-11-19 [contacts-E 2026-11-19] next_step_due was 2026-11-17 (stale), now 2027-01-11 to match the grant row e51fa940 (eligibility quiz, In-Kind pathway, January 2027). Step text, stage and ball_with unchanged.$t$ where id='e78be2ab-7724-46e8-8828-48f72e20be6b' and next_step_due::date='2026-11-17' and next_step=$t$Check foundation site for the next Community Music Grants window and eligibility$t$ and coalesce(notes,'') not like '%[contacts-E 2026-11-19]%';
commit;
select id, name, stage, ball_with, next_step_due, email from fs_partners where id in ('414dde79-6b11-4c98-ae44-dcdc579bcb64','d8211717-4fab-4c5d-86ab-ff62b95010e2','6e21e33a-c72b-4133-a646-f552e5087f01','b7c1e5a2-3d4f-4a6b-9c8d-1e2f3a4b5c6d','e78be2ab-7724-46e8-8828-48f72e20be6b'); -- expect 5 rows: us/2026-11-23 for the first four, e78be2ab us/2027-01-11
select id, funder, status, next_step_due, url from fs_grant_deadlines where notes like '%[contacts-E 2026-11-19]%'; -- expect 4 rows: a4287c9e ready 2026-11-23; de947322 ready 2026-11-23 typeform url; e562dd73 to_research 2026-11-23; 94f4ffa2 ready 2026-11-23
